			this.bitmap_click.set_alpha(0);
			this.textField.set_scaleX(this.textField.set_scaleY(this.normalScale));
			this.textField.set_x(this.textField.get_width() * this.textField.get_scaleX() / -2);
			this.textField.set_y(this.textField.get_height() * this.textField.get_scaleY() / -2 - 1);
