	,onPause: function(ME) {
		if(!scenes_Gameplay.game_paused) {
			motion_Actuate.tween(this.pause_board,0.5,{ x : 0}).ease(motion_easing_Quad.get_easeOut());
			motion_Actuate.tween(this.pause_fade,0.5,{ alpha : 0.35}).ease(motion_easing_Quad.get_easeOut());
			scenes_Gameplay.game_paused = true;
			this.btn_continue.mouseEnabled = true;
			this.btn_quit.mouseEnabled = true;
			this.fade.mouseEnabled = true;
			utils_SoundLib.playFX("pause");
		} else this.onContinue();
	}
	,onContinue: function(ME) {
		motion_Actuate.tween(this.pause_board,0.5,{ x : Main.screenWidth + 60}).ease(motion_easing_Quad.get_easeOut());
		motion_Actuate.tween(this.pause_fade,0.5,{ alpha : 0}).ease(motion_easing_Quad.get_easeOut());
		scenes_Gameplay.game_paused = false;
		this.btn_continue.mouseEnabled = false;
		this.btn_quit.mouseEnabled = false;
		this.fade.mouseEnabled = false;
		utils_SoundLib.playFX("boton on");
	}
	,onQuit: function(ME) {
		utils_DataManager.checkUnlockedBears();
		this.fade.mouseEnabled = false;
		this.btn_quit.mouseEnabled = false;
		scenes_Manager.go("levelselector");
		utils_SoundLib.playFX("cancel");
	}
	,onRestart: function(ME) {
		this.fade.mouseEnabled = false;
		this.btn_restart.mouseEnabled = false;
		scenes_Manager.go("restart");
		utils_SoundLib.playFX("move checker");
	}
