	edgeSideTop.setAsEdge(new box2D_common_math_B2Vec2(-edgeSideX,-edgeSideY),new box2D_common_math_B2Vec2(edgeSideX,-edgeSideY));
	var filter = new box2D_dynamics_B2FilterData();
	filter.categoryBits = gameplay_collisions_CollisionFlag.BEAR;
	filter.maskBits = gameplay_collisions_CollisionFlag.WALL;
