	fixtureDefinitionSideRight.restitution = 0.01;
	fixtureDefinitionSideRight.density = 1;
	fixtureDefinitionSideRight.userData = "right";
	fixtureDefinitionSideRight.filter = filter;
	var fixtureDefinitionSideTop = new box2D_dynamics_B2FixtureDef();
	fixtureDefinitionSideTop.shape = edgeSideTop;
	fixtureDefinitionSideTop.friction = 0;
	fixtureDefinitionSideTop.restitution = 0.1;
	fixtureDefinitionSideTop.userData = "top";
	fixtureDefinitionSideTop.filter = filter;
	this.body = scenes_Gameplay.world.createBody(bodyDefinition);
	this.body.setSleepingAllowed(false);
