	,checkSemisolid: function(fixtureA,fixtureB,userData) {
		var body;
		if(fixtureA.getUserData() == "semisolid") {
			if(fixtureB.getUserData() == userData) {
				if(fixtureB.getBody().getLinearVelocity().y >= 0) return true;
			}
		}
		if(fixtureB.getUserData() == "semisolid") {
			if(fixtureA.getUserData() == userData) {
				if(fixtureA.getBody().getLinearVelocity().y >= 0) return true;
			}
		}
		return false;
	}
	,checkSemisolidSemisolid: function(fixtureA,fixtureB) {
		if(fixtureA.getUserData() == "semisolid" && fixtureB.getUserData() == "semisolid") return true;
		return false;
	}
	,get: function(fixtureA,fixtureB,object) {
		if(fixtureA.getUserData() == object) return fixtureA.getBody().getUserData();
		if(fixtureB.getUserData() == object) return fixtureB.getBody().getUserData();
		return null;
	}
