	,sleep: function() {
		this.removeEventListener("mouseDown",$bind(this,this.onDown));
		this.removeEventListener("mouseUp",$bind(this,this.onUp));
		this.removeEventListener("mouseMove",$bind(this,this.onDrag));
		if(Main.multiTouchSupported) {
			this.removeEventListener("touchBegin",$bind(this,this.onDown));
			this.removeEventListener("touchEnd",$bind(this,this.onUp));
			this.removeEventListener("touchMove",$bind(this,this.onDrag));
		}
	}
	,showChecker: function() {
		if(utils_DataManager.panda_spawn) {
			utils_DataManager.panda_spawn = false;
			levelselect_Checker.playAnimation("grizzly");
			motion_Actuate.timer(2.0).onComplete($bind(this,this.playSpawnPanda));
			motion_Actuate.timer(3.0).onComplete($bind(this,this.gotoNewLevel));
		} else if(utils_DataManager.polar_spawn) {
			levelselect_Checker.playAnimation("panda");
			utils_DataManager.polar_spawn = false;
			motion_Actuate.timer(2.0).onComplete($bind(this,this.playSpawnPolar));
			motion_Actuate.timer(3.0).onComplete($bind(this,this.gotoNewLevel));
		} else {
			if(utils_DataManager.polar_available) levelselect_Checker.playAnimation("polar"); else if(utils_DataManager.panda_available) levelselect_Checker.playAnimation("panda"); else if(utils_DataManager.grizzly_available) levelselect_Checker.playAnimation("grizzly");
			motion_Actuate.timer(1.5).onComplete($bind(this,this.gotoNewLevel));
		}
	}
	,playSpawnPanda: function() {
		levelselect_Checker.playAnimation("spawn-panda");
	}
	,playSpawnPolar: function() {
		levelselect_Checker.playAnimation("spawn-polar");
	}
	,createDebug: function() {
		this.btn_pardo = new buttons_Button($bind(this,this.setPardoEnabled),"",null,"img/interface/selector 1 no seleccionado.png");
		this.btn_pardo.set_x(50);
		this.btn_pardo.set_y(30);
		this.btn_panda = new buttons_Button($bind(this,this.setPandaEnabled),"",null,"img/interface/selector 2 no seleccionado.png");
		this.btn_panda.set_x(100);
		this.btn_panda.set_y(30);
		this.btn_polar = new buttons_Button($bind(this,this.setPolarEnabled),"",null,"img/interface/selector 3 no seleccionado.png");
		this.btn_polar.set_x(150);
		this.btn_polar.set_y(30);
		this.addChild(this.btn_pardo);
		this.addChild(this.btn_panda);
		this.addChild(this.btn_polar);
	}
	,setPardoEnabled: function() {
		utils_DataManager.grizzly_available = true;
		utils_DataManager.panda_available = false;
		utils_DataManager.polar_available = false;
		levelselect_Checker.playAnimation("spawn");
	}
	,setPandaEnabled: function() {
		utils_DataManager.grizzly_available = true;
		utils_DataManager.panda_available = true;
		utils_DataManager.polar_available = false;
		levelselect_Checker.playAnimation("spawn");
	}
	,setPolarEnabled: function() {
		utils_DataManager.grizzly_available = true;
		utils_DataManager.panda_available = true;
		utils_DataManager.polar_available = true;
		levelselect_Checker.playAnimation("spawn");
	}
	,createHUD: function() {
		this.btn_back = new buttons_Button($bind(this,this.goMainMenu),"",null,"img/interface/botones (superiores) home.png");
		this.btn_back.set_x(Main.screenWidth - 70);
		this.btn_back.set_y(30);
		this.btn_sound_on = new buttons_Button($bind(this,this.onMute),"",null,"img/interface/botones (superiores) sonido on.png");
		this.btn_sound_on.set_x(Main.screenWidth - 30);
		this.btn_sound_on.set_y(30);
		this.btn_sound_off = new buttons_Button($bind(this,this.onMute),"",null,"img/interface/botones (superiores) sonido off.png");
		this.btn_sound_off.set_x(Main.screenWidth - 30);
		this.btn_sound_off.set_y(30);
		this.fixMuteButton();
		this.btn_bitmapdata = openfl_Assets.getBitmapData("img/interface/botones (superiores) contenedor.png");
		this.btn_bg = new openfl_display_Bitmap(this.btn_bitmapdata,0,true);
		this.btn_bg.set_x(this.btn_sound_on.get_x() - this.btn_bg.get_width() / 2);
		this.btn_bg.set_y(this.btn_sound_on.get_y() - this.btn_bg.get_height() / 2);
		this.btn_bg2 = new openfl_display_Bitmap(this.btn_bitmapdata,0,true);
		this.btn_bg2.set_x(this.btn_back.get_x() - this.btn_bg2.get_width() / 2);
		this.btn_bg2.set_y(this.btn_back.get_y() - this.btn_bg2.get_height() / 2);
		this.addChild(this.btn_bg);
		this.addChild(this.btn_bg2);
		this.addChild(this.btn_back);
		this.addChild(this.btn_sound_on);
		this.addChild(this.btn_sound_off);
	}
	,createCard: function() {
		this.card = new levelselect_Card();
		this.card.set_x(Main.screenWidth / 2 - this.card.get_width() / 2);
		this.card.set_y(Main.screenHeight + 50);
		this.addChild(this.card);
		if(levelselect_Checker.actual.id != 0 && levelselect_Checker.actual.id != 17) motion_Actuate.timer(2.0).onComplete(($_=this.card,$bind($_,$_.cardIn)));
	}
	,goMainMenu: function(ME) {
		if(!scenes_LevelSelector.buttonsEnabled) return;
		this.sleep();
		scenes_LevelSelector.buttonsEnabled = false;
		utils_SoundLib.playFX("cancel");
		scenes_Manager.go("mainmenu");
	}
	,gotoNewLevel: function() {
		if(utils_DataManager.newLevel != -1) this.array_button[utils_DataManager.newLevel].moveOnMy();
		utils_DataManager.newLevel = -1;
	}
	,onMute: function(ME) {
		utils_SoundLib.mute = !utils_SoundLib.mute;
		utils_SoundLib.muteMusic();
		this.fixMuteButton();
	}
	,fixMuteButton: function() {
		if(utils_SoundLib.mute) {
			this.btn_sound_on.set_visible(false);
			this.btn_sound_off.set_visible(true);
		} else {
			this.btn_sound_on.set_visible(true);
			this.btn_sound_off.set_visible(false);
		}
	}
	,added: function() {
		while(scenes_LevelSelector.shadows.get_numChildren() > 0) scenes_LevelSelector.shadows.removeChildAt(0);
		this.awake();
		scenes_LevelSelector.buttonsEnabled = true;
		this.addEventListener("enterFrame",$bind(this,this.update));
	}
	,removed: function() {
		this.pj.onRemoved();
		try {
			this.removeChild(this.pj);
		} catch( e ) {
			haxe_CallStack.lastException = e;
			if (e instanceof js__$Boot_HaxeError) e = e.val;
			if( js_Boot.__instanceof(e,openfl_errors_Error) ) {
			} else throw(e);
		}
		this.sleep();
		this.removeEventListener("enterFrame",$bind(this,this.update));
		levelselect_Checker.remove();
	}
	,onDown: function(ME) {
		if(!scenes_LevelSelector.buttonsEnabled) return;
		this.mouseIsDown = true;
		this.clickX = ME.stageX;
		this.lastX = this.board.get_x();
		this.addChild(this.pj);
	}
	,onUp: function(ME) {
		if(!scenes_LevelSelector.buttonsEnabled) return;
		this.mouseIsDown = false;
		this.dragTimer = 0;
	}
	,onDrag: function(ME) {
		if(!scenes_LevelSelector.buttonsEnabled) return;
		if(this.mouseIsDown) {
			this.dragTimer++;
			if(this.dragTimer <= 5) return;
		}
		if(!this.mouseIsDown || levelselect_Checker.moving) return;
		this.camera_lock = false;
		this.board.set_x(this.lastX + (ME.stageX - this.clickX));
		this.setView();
	}
	,movingView: function() {
		this.lastX = this.board.get_x();
		var dx = this.lastX - (this.pj.get_x() - 320);
		var dif = (dx - this.board.get_x()) / 20;
		if(Math.abs(dif) > .5) {
			var _g = this.board;
			_g.set_x(_g.get_x() + dif);
		}
		this.setView();
	}
	,setView: function() {
		var myRange = Main.screenWidth - this.board.get_width();
		if(this.board.get_x() > myRange * .25) this.board.set_x(myRange * .25);
		if(this.board.get_x() < myRange * .75) this.board.set_x(myRange * .75);
		this.wall.set_x(this.board.get_x() * .6);
		this.bears.set_x(this.board.get_x());
		var myPercentage;
		myPercentage = this.board.get_x() / myRange;
	}
